// Normalize inbound failure for Grok Watchdog audit sink.
// Register Scorpion is leftover — NOT the audit sink.
const body = $json.body || $json;

const correlationId = body.correlationId || body.correlation_id || `self-heal-${Date.now()}`;
const route = body.route || body.path || 'unknown';
const statusCode = Number(body.statusCode || body.status_code || 500);
const error = body.error || body.message || 'unknown error';
const stack = body.stack || body.stackTrace || body.stack_trace || '';
const repo = body.repo || 'n8n-cursor';
const service = body.service || body.serviceName || 'hive';
const fixAttempt = Number(body.fix_attempt || body.fixAttempt || 0);
const toolMethod = body.toolMethod || body.tool_method || '';
const businessGoal = body.businessGoal || body.business_goal || '';
const escalatePivot = fixAttempt >= 3;
const status = escalatePivot ? 'escalate_pivot' : 'need_hitl';

const text = [
  'Self-heal proposed (Tier 3 merge required)',
  `cid: ${correlationId}`,
  `route: ${route}`,
  `statusCode: ${statusCode}`,
  `error: ${error}`,
  stack ? `stack: ${stack}` : '',
  `repo: ${repo}`,
  `service: ${service}`,
  `fixAttempt: ${fixAttempt}`,
  toolMethod ? `toolMethod: ${toolMethod}` : '',
  businessGoal ? `businessGoal: ${businessGoal}` : '',
  escalatePivot
    ? 'Escalate to hive-creative-pivot (fix_attempt>=3). Forge: branch · patch · test · PR. Operator merges.'
    : 'Forge: branch · patch · test · PR. Operator merges.'
].filter(Boolean).join('\n');

return [{
  json: {
    correlationId,
    status,
    error,
    route,
    statusCode,
    stack,
    repo,
    service,
    fixAttempt,
    toolMethod,
    businessGoal,
    escalatePivot,
    text,
    registerPayload: {
      serviceName: service || 'hive-error-heal',
      version: '1.0.0',
      host: 'evenslouis.ca',
      port: 443,
      protocol: 'https',
      status: 'unhealthy',
      metadata: {
        correlationId,
        source: 'hive-error-heal',
        jobType: 'ops.self_heal.proposed',
        summary: text.slice(0, 500),
        triggeredAt: new Date().toISOString()
      },
      tags: ['hive', 'error-heal', 'need_hitl']
    }
  }
}];
